-- #115 계정 유형 (ADR-0107 결정 4 #115 rows, 결정 2 #73 11항, 결정 3, 결정 5 #179·#119 row;
-- ADR-0108). Generated by `drizzle-kit generate`, then hand-edited where marked: this header and
-- the tail. The snapshot is as generated. Additive (결정 3: the deployed database is emptied by
-- #116, not here): every account already there becomes '일반 사용자' through the column's default,
-- a catalog-only change; the triggers below judge new rows only.
--
-- - account_type: '일반 사용자' (`member`) or '운영 마켓메이커' (`market_maker`) — no test-account
--   and no system type (the treasury and the collateral are #116's ledger accounts). On
--   better-auth's "user" row, so it is known when the row is inserted; the default labels every
--   sign-up, and no client input sets it. The admin role stays on `profiles.role`, apart from it.
-- - user_market_maker_uidx: one 운영 마켓메이커 account, which the seed makes when it is missing
--   (`ensureMarketMakerAccount`, @buddha/db).
CREATE TYPE "public"."account_type" AS ENUM('member', 'market_maker');--> statement-breakpoint
ALTER TABLE "user" ADD COLUMN "account_type" "account_type" DEFAULT 'member' NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "user_market_maker_uidx" ON "user" USING btree ("account_type") WHERE "user"."account_type" = 'market_maker';--> statement-breakpoint
-- Hand-edited: the one rule that says whether an account is a person's (사람 계정, N04 §2·§5),
-- in SQL — `isHumanAccountType` in @buddha/shared is the same rule, and the schema test keeps the
-- two in agreement. By type, IMMUTABLE so the planner inlines it into a join over "user"
-- (`isHumanAccountTypeSql`: participants and volume, #121; '사용자 체결 0건', #20); and by account
-- id (`isHumanAccountSql`), the shape a row's owner column takes — an order's or a fill's through
-- its `user_id`, a ledger account's through its owner (#116). Unknown or NULL is not a person: a
-- ledger account with no owner (the treasury, the collateral) and one the 운영 마켓메이커 owns
-- (its funds per market) read false alike. Runs as the invoker; EXECUTE comes with the default
-- privileges of docker/postgres/init/01-roles.sql.
CREATE FUNCTION is_human_account_type(kind account_type) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT kind = 'member';
$$;--> statement-breakpoint
CREATE FUNCTION is_human_account(account_id text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM "user" u WHERE u.id = account_id AND is_human_account_type(u.account_type)
  );
$$;--> statement-breakpoint
-- Hand-edited: an account's type is fixed when the account is made (ADR-0107 결정 4 #115: 유형의
-- 변경은 DB 트리거가 거절한다), whoever writes — buddha_app, the migration role, a script — as
-- start_grants_keep_record (0031, ADR-0071) keeps a grant. better-auth's own updates (the address,
-- its verification, `updated_at`) and a closure's address never name another type and pass, and so
-- does a write of the same type. TRUNCATE fires no row trigger: the wipe still empties "user".
CREATE FUNCTION user_keep_account_type() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'account % is % from its creation: its type takes no change to %', OLD.id,
    OLD.account_type, NEW.account_type
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;--> statement-breakpoint
CREATE TRIGGER user_keep_account_type
  BEFORE UPDATE ON "user"
  FOR EACH ROW WHEN (NEW.account_type IS DISTINCT FROM OLD.account_type)
  EXECUTE FUNCTION user_keep_account_type();--> statement-breakpoint
-- Hand-edited: the 운영 마켓메이커 gets no profile (ADR-0107 결정 2 #73 11항: 공개 프로필은 404,
-- 자동 닉네임·소개 없음, 관리자 화면에서만 '운영 마켓메이커'). The function is re-created whole with
-- 0032's body, and one branch comes first: an account of a type that is not a person's gets its
-- zero balance (the ledger audit reads every account's, PLAN 5.6) and nothing else — no profile,
-- so no nickname, no 소개, no image, no public id (no profile address exists), no admin role (it
-- lives on the profile) and no onboarding step done. A person's account is made as before: the
-- profile with 'user_' + four characters, each candidate locked and skipped while held (#57-6),
-- and a zero balance, no grant, in the same transaction as the user row (ADR-0019).
CREATE OR REPLACE FUNCTION create_profile_for_user() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  -- 32 unambiguous upper-case letters and digits (no 0/O/1/I): 32^4 = 1,048,576 suffixes.
  alphabet CONSTANT text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text;
  i integer;
  attempt integer := 0;
BEGIN
  IF NOT is_human_account_type(NEW.account_type) THEN
    INSERT INTO balances (user_id) VALUES (NEW.id);
    RETURN NEW;
  END IF;
  LOOP
    attempt := attempt + 1;
    candidate := 'user_';
    FOR i IN 1..4 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * 32)::integer, 1);
    END LOOP;
    PERFORM lock_nickname(candidate);
    IF NOT nickname_held(candidate, NEW.id) THEN
      BEGIN
        INSERT INTO profiles (user_id, nickname) VALUES (NEW.id, candidate);
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF attempt >= 10 THEN RAISE; END IF;
      END;
    END IF;
    IF attempt >= 10 THEN
      RAISE EXCEPTION 'no free auto nickname for % after % candidates', NEW.id, attempt
        USING ERRCODE = 'unique_violation';
    END IF;
  END LOOP;
  INSERT INTO balances (user_id) VALUES (NEW.id);
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: nor does an operating account ever take a row of what a person has (ADR-0107 결정 2
-- #73 11항): a profile (above), a login method — a session, a sign-in method, a password-reset
-- token naming it (그 계정에는 로그인 수단이 없다) —, a start grant (#70), and the public activity
-- the server refuses it (글·댓글·좋아요·신고·시장 제안을 서버가 거절한다). Whatever writes them: the
-- API reaches none of these for it (no session, no onboarding), and this keeps a later code path
-- from doing so. One function, the owner column named by the trigger's argument, raised with the
-- trigger's name as the constraint as refuse_closed_account_rows (0043) is. An unknown account
-- passes to its foreign key, which refuses it as before. No lock: the type never changes (above).
-- The other tables an account writes (consents, 본인확인, watches, searches, media, disputes) are
-- reached only through a session, which the operating account cannot have.
CREATE FUNCTION refuse_operating_account_rows() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  holder text := to_jsonb(NEW) ->> TG_ARGV[0];
  kind account_type;
BEGIN
  SELECT u.account_type INTO kind FROM "user" u WHERE u.id = holder;
  IF FOUND AND NOT is_human_account_type(kind) THEN
    RAISE EXCEPTION 'account % is an operating account (#115): % takes no row of it', holder,
      TG_TABLE_NAME
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER profiles_human_account
  BEFORE INSERT ON "profiles"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER session_human_account
  BEFORE INSERT ON "session"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER account_human_account
  BEFORE INSERT ON "account"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER verification_human_account
  BEFORE INSERT ON "verification"
  FOR EACH ROW WHEN (NEW.identifier LIKE 'reset-password:%')
  EXECUTE FUNCTION refuse_operating_account_rows('value');--> statement-breakpoint
CREATE TRIGGER start_grants_human_account
  BEFORE INSERT ON "start_grants"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER posts_human_account
  BEFORE INSERT ON "posts"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('author_id');--> statement-breakpoint
CREATE TRIGGER post_comments_human_account
  BEFORE INSERT ON "post_comments"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('author_id');--> statement-breakpoint
CREATE TRIGGER post_likes_human_account
  BEFORE INSERT ON "post_likes"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER comment_likes_human_account
  BEFORE INSERT ON "comment_likes"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
CREATE TRIGGER reports_human_account
  BEFORE INSERT ON "reports"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('reporter_id');--> statement-breakpoint
CREATE TRIGGER market_proposals_human_account
  BEFORE INSERT ON "market_proposals"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');